// Types mirroring the backend contract (see the OpenAPI schema at /docs).

export type EvalMethod =
  | "exact_match"
  | "numeric"
  | "regex"
  | "json_schema"
  | "code_exec"
  | "sql_exec"
  | "bleu"
  | "rouge_l"
  | "fuzzy"
  | "llm_judge"
  | "llm_judge_pairwise"
  | "ensemble_judge";

export type EvalTier = "deterministic" | "similarity" | "llm_judge" | "advanced";

export type Provider = "openai_compat" | "anthropic" | "fake";

export interface ModelSpec {
  id: string;
  display_name: string;
  provider: Provider;
  model_id: string;
  base_url?: string | null;
  api_key_env?: string | null;
  role: string;
  supports_reasoning: boolean;
}

export interface RunParams {
  temperature: number;
  max_tokens: number;
  top_p?: number | null;
  top_k?: number | null;
  reasoning_effort?: string | null;
  seed?: number | null;
  stop?: string[] | null;
  presence_penalty?: number | null;
  frequency_penalty?: number | null;
}

export interface EvaluatorInfo {
  method: EvalMethod;
  tier: EvalTier;
  label: string;
  description: string;
  required_fields: string[];
  needs_judge: boolean;
}

export interface DatasetSummary {
  category: string;
  count: number;
  methods: string[];
}

export interface EvalCase {
  id: string;
  category: string;
  prompt: string;
  default_method: EvalMethod;
  reference?: string | null;
  tests?: string | null;
  sql_schema?: string | null;
  json_schema?: Record<string, unknown> | null;
  rubric?: string[] | null;
  subcategory?: string | null;
  lang?: string | null;
  max_tokens?: number | null;
}

export interface Usage {
  prompt_tokens: number;
  completion_tokens: number;
  total_tokens: number;
  cost_usd: number;
  latency_ms: number;
}

export interface Score {
  method: EvalMethod;
  value: number;
  passed?: boolean | null;
  detail: string;
  dimensions?: Record<string, number> | null;
  judge_model?: string | null;
  usage?: Usage | null;
}

export interface CellResult {
  case_id: string;
  model_id: string;
  label?: string | null;
  params: RunParams;
  response: string;
  usage: Usage;
  scores: Score[];
  error?: string | null;
}

export interface CandidateConfig {
  model_id: string;
  params?: RunParams;
  prompt_override?: string | null;
  label?: string | null;
}

export interface Run {
  id: string;
  status: string;
  results: CellResult[];
  total_cells: number;
  completed_cells: number;
  error?: string | null;
  created_at?: string | null;
}

export interface JudgeAgreement {
  pearson: number;
  spearman: number;
  rank_agreement: number;
  mae_overall: number;
  mae_by_dimension: Record<string, number>;
  verdict: string;
  sample_size: number;
}

export interface EvaluateRequest {
  model_id: string;
  methods: EvalMethod[];
  params?: RunParams;
  judge_model_id?: string | null;
  judge_params?: RunParams;
  case_id?: string | null;
  prompt_override?: string | null;
  prompt?: string | null;
  reference?: string | null;
  rubric?: string[] | null;
  tests?: string | null;
  sql_schema?: string | null;
}

export interface RunRequest {
  case_ids: string[];
  candidates: CandidateConfig[];
  methods: EvalMethod[];
  judge_model_id?: string | null;
  judge_params?: RunParams;
}

export interface JudgeAgreementRequest {
  run_id: string;
  reference_judge_model_id: string;
  sample_size?: number;
  judge_params?: RunParams;
}

export const DEFAULT_PARAMS: RunParams = {
  temperature: 0,
  max_tokens: 1024,
};
